int ledPin = 13; // Arduino'dagi o'rnatilgan LED ulangan pin

void setup() {
  // 1 marta ishlaydi: pin chiqish (OUTPUT) rejimiga sozlanmoqda
  pinMode(ledPin, OUTPUT); 
}

void loop() {
  // Cheksiz marta takrorlanadi:
  digitalWrite(ledPin, HIGH); // LED chirog'ini yoqish (5V berish)
  delay(1000);                // 1 soniya (1000 ms) kutib turish

  digitalWrite(ledPin, LOW);  // LED chirog'ini o'chirish (0V berish)
  delay(1000);                // Yana 1 soniya kutib turish
}
